// Kumo-derived values: Copyright (c) 2026 Cloudflare, Inc. (MIT). See ../LICENSE.
// No reset, default palette, component CSS, or remote fonts are imported.
@use './light';
@use './dark';

// Shared visual values are emitted in both modes so explicit light/dark markers reset them.
@mixin values {
	--accent: var(--tile-tint);
	--accent-foreground: var(--tile-text-default);
	--background: var(--tile-canvas);
	--border: var(--tile-line);
	--card: var(--tile-surface-base);
	--card-foreground: var(--tile-text-default);
	--chart-1: var(--tile-brand);
	--chart-2: var(--tile-success);
	--chart-3: var(--tile-warning);
	--chart-4: oklch(55.8% 0.288 302.321);
	--chart-5: var(--tile-danger);
	--destructive: var(--tile-danger);
	--destructive-foreground: #fff;
	--foreground: var(--tile-text-default);
	--input: var(--tile-line);
	--muted: var(--tile-surface-recessed);
	--muted-foreground: var(--tile-text-subtle);
	--popover: var(--tile-surface-base);
	--popover-foreground: var(--tile-text-default);
	--primary: var(--tile-brand);
	--primary-foreground: #fff;
	--radius: 0.5rem;
	--ring: var(--tile-focus);
	--secondary: var(--tile-surface-elevated);
	--secondary-foreground: var(--tile-text-default);
	--sidebar: var(--tile-surface-elevated);
	--sidebar-accent: var(--tile-tint);
	--sidebar-accent-foreground: var(--tile-text-default);
	--sidebar-border: var(--tile-hairline);
	--sidebar-foreground: var(--tile-text-default);
	--sidebar-primary: var(--tile-brand);
	--sidebar-primary-foreground: #fff;
	--sidebar-ring: var(--tile-focus);
	--tile-accordion-border: var(--tile-hairline);
	--tile-accordion-focus-shadow: inset 0 0 0 2px var(--tile-brand);
	--tile-accordion-font-size: var(--tile-text-base);
	--tile-accordion-foreground: var(--foreground);
	--tile-accordion-hover-background: var(--tile-tint);
	--tile-accordion-hover-decoration: none;
	--tile-accordion-radius: 0.375rem;
	--tile-accordion-subtle: var(--tile-text-subtle);
	--tile-alert-background: var(--tile-info-tint);
	--tile-alert-border: transparent;
	--tile-alert-color: var(--tile-text-info);
	--tile-alert-description-color: var(--tile-text-info);
	--tile-alert-description-leading: 1.375;
	--tile-alert-dialog-background: var(--tile-surface-base);
	--tile-alert-dialog-border: var(--tile-line);
	--tile-alert-dialog-description-color: var(--tile-text-subtle);
	--tile-alert-dialog-description-size: var(--tile-text-base);
	--tile-alert-dialog-max-width: 24rem;
	--tile-alert-dialog-overlay: var(--tile-dialog-overlay);
	--tile-alert-dialog-padding: 2rem;
	--tile-alert-dialog-radius: 0.75rem;
	--tile-alert-dialog-shadow: var(--tile-dialog-shadow);
	--tile-alert-dialog-sm-max-width: 18rem;
	--tile-alert-dialog-title-leading: 1.75rem;
	--tile-alert-dialog-title-size: 1.25rem;
	--tile-alert-dialog-top: 2rem;
	--tile-alert-dialog-top-desktop: 4rem;
	--tile-alert-dialog-translate-y: 0%;
	--tile-alert-error-background: var(--tile-danger-tint);
	--tile-alert-error-border: transparent;
	--tile-alert-error-color: var(--tile-text-danger);
	--tile-alert-font-size: var(--tile-text-base);
	--tile-alert-padding: 0.75rem 1rem;
	--tile-alert-radius: 0.5rem;
	--tile-alert-title-leading: 1.375;
	--tile-alert-title-tracking: normal;
	--tile-attachment-background: var(--tile-surface-base);
	--tile-attachment-border: var(--tile-line);
	--tile-attachment-error-background: var(--tile-danger-tint);
	--tile-attachment-error-border: var(--tile-danger);
	--tile-attachment-error-color: var(--tile-text-danger);
	--tile-attachment-focus-shadow: 0 0 0 2px var(--tile-focus);
	--tile-attachment-hover-background: var(--tile-surface-elevated);
	--tile-attachment-media-background: var(--tile-surface-recessed);
	--tile-attachment-radius: 0.5rem;
	--tile-avatar-background: var(--tile-surface-recessed);
	--tile-avatar-color: var(--tile-text-subtle);
	--tile-badge-border-width: 0px;
	--tile-badge-default-hover-background: var(--tile-badge-default-background);
	--tile-badge-destructive-color: #fff;
	--tile-badge-destructive-hover-background: var(--tile-badge-destructive-background);
	--tile-badge-line-height: 1.333333;
	--tile-badge-link-hover-outline: 1px solid currentColor;
	--tile-badge-outline-background: var(--tile-surface-base);
	--tile-badge-outline-border: var(--tile-fill);
	--tile-badge-outline-border-width: 1px;
	--tile-badge-padding: 0.125rem 0.5rem;
	--tile-badge-secondary-background: var(--tile-fill);
	--tile-badge-secondary-hover-background: var(--tile-fill);
	--tile-breadcrumb-active-foreground: var(--foreground);
	--tile-breadcrumb-font-size: var(--tile-text-base);
	--tile-breadcrumb-foreground: var(--tile-text-subtle);
	--tile-breadcrumb-gap: 0.25rem;
	--tile-breadcrumb-page-font-weight: 500;
	--tile-breadcrumb-separator: var(--tile-text-inactive);
	--tile-breadcrumb-separator-size: 1.5rem;
	--tile-bubble-background: var(--tile-brand);
	--tile-bubble-border: var(--tile-line);
	--tile-bubble-color: #fff;
	--tile-bubble-error-background: var(--tile-danger-tint);
	--tile-bubble-error-color: var(--tile-text-danger);
	--tile-bubble-error-hover-background: color-mix(in srgb, var(--tile-danger) 20%, var(--tile-surface-base));
	--tile-bubble-focus-shadow: 0 0 0 2px var(--tile-focus);
	--tile-bubble-hover-background: var(--tile-brand-hover);
	--tile-bubble-muted-background: var(--tile-surface-recessed);
	--tile-bubble-outline-background: var(--tile-surface-base);
	--tile-bubble-padding: 0.5rem 0.75rem;
	--tile-bubble-radius: 0.5rem;
	--tile-bubble-reactions-background: var(--tile-surface-recessed);
	--tile-bubble-secondary-background: var(--tile-surface-elevated);
	--tile-bubble-tinted-background: var(--tile-tint);
	--tile-button-compact-line-height: 1.3333333333;
	--tile-button-default-active-background: var(--tile-brand);
	--tile-button-default-active-background-image: linear-gradient(to bottom, color-mix(in oklch, var(--tile-brand), white 15%), var(--tile-brand));
	--tile-button-default-background: color-mix(in oklch, var(--tile-brand), white 30%);
	--tile-button-default-background-image: linear-gradient(to bottom, color-mix(in oklch, var(--tile-brand), white 15%), var(--tile-brand));
	--tile-button-default-color: #fff;
	--tile-button-default-focus-shadow:
		inset 0 1px 0 0 color-mix(in oklch, var(--tile-brand), white 30%), 0 0 0 2px color-mix(in oklch, var(--tile-brand), black 10%), var(--tile-shadow-sm);
	--tile-button-default-hover-background: color-mix(in oklch, var(--tile-brand), white 30%);
	--tile-button-default-hover-background-image: linear-gradient(to bottom, color-mix(in oklch, var(--tile-brand), white 30%), var(--tile-brand));
	--tile-button-default-shadow:
		inset 0 1px 0 0 color-mix(in oklch, var(--tile-brand), white 30%), 0 0 0 1px color-mix(in oklch, var(--tile-brand), black 10%), var(--tile-shadow-sm);
	--tile-button-destructive-background: color-mix(in oklch, var(--destructive), white 30%);
	--tile-button-destructive-background-image: linear-gradient(to bottom, color-mix(in oklch, var(--destructive), white 15%), var(--destructive));
	--tile-button-destructive-color: #fff;
	--tile-button-destructive-hover-background: color-mix(in oklch, var(--destructive), white 30%);
	--tile-button-destructive-hover-background-image: linear-gradient(to bottom, color-mix(in oklch, var(--destructive), white 30%), var(--destructive));
	--tile-button-destructive-shadow:
		inset 0 1px 0 0 color-mix(in oklch, var(--destructive), white 30%), 0 0 0 1px color-mix(in oklch, var(--destructive), black 10%), var(--tile-shadow-sm);
	--tile-button-focus-outline: auto 1px -webkit-focus-ring-color;
	--tile-button-focus-outline-offset: 0px;
	--tile-button-focus-outline-style: none;
	--tile-button-font-family: var(--tile-font-sans);
	--tile-button-font-size: var(--tile-text-base);
	--tile-button-gap: 0.375rem;
	--tile-button-ghost-background: inherit;
	--tile-button-ghost-color: var(--foreground);
	--tile-button-ghost-hover-background: var(--accent);
	--tile-button-ghost-hover-color: var(--foreground);
	--tile-button-ghost-shadow: none;
	--tile-button-group-background: var(--tile-surface-recessed);
	--tile-button-group-border: var(--tile-line);
	--tile-button-group-focus-z-index: 10;
	--tile-button-group-font-size: var(--tile-text-base);
	--tile-button-group-isolation: isolate;
	--tile-button-group-position: relative;
	--tile-button-group-radius: 0.5rem;
	--tile-button-group-seam-overlap: -1px;
	--tile-button-group-separator: var(--tile-line);
	--tile-button-height: 2.25rem;
	--tile-button-icon-padding-inline: 0.625rem;
	--tile-button-icon-size: 1rem;
	--tile-button-icon-sm-radius: 0.375rem;
	--tile-button-icon-xs-size: 0.875rem;
	--tile-button-lg-font-size: var(--tile-text-base);
	--tile-button-lg-gap: 0.5rem;
	--tile-button-lg-height: 2.5rem;
	--tile-button-lg-icon-padding-inline: 0.875rem;
	--tile-button-lg-padding-block: 0 0.125rem;
	--tile-button-lg-padding-inline: 1rem;
	--tile-button-lg-radius: 0.5rem;
	--tile-button-line-height: 1.5;
	--tile-button-outline-background: transparent;
	--tile-button-outline-border-width: 0px;
	--tile-button-outline-color: var(--foreground);
	--tile-button-outline-hover-background: transparent;
	--tile-button-outline-hover-color: var(--tile-text-strong);
	--tile-button-outline-hover-shadow: 0 0 0 1px color-mix(in oklch, var(--tile-focus) 25%, transparent), var(--tile-shadow-sm);
	--tile-button-outline-shadow: 0 0 0 1px var(--tile-line), var(--tile-shadow-sm);
	--tile-button-padding-block: 0 0.125rem;
	--tile-button-padding-inline: 0.75rem;
	--tile-button-radius: 0.5rem;
	--tile-button-secondary-background: var(--tile-surface-base);
	--tile-button-secondary-color: var(--foreground);
	--tile-button-secondary-disabled-background: color-mix(in oklab, var(--tile-surface-base) 50%, transparent);
	--tile-button-secondary-disabled-color: color-mix(in oklab, var(--foreground) 70%, transparent);
	--tile-button-secondary-focus-shadow: 0 0 0 2px var(--tile-brand), var(--tile-shadow-sm);
	--tile-button-secondary-hover-background: var(--accent);
	--tile-button-secondary-shadow: 0 0 0 1px var(--tile-line), var(--tile-shadow-sm);
	--tile-button-sm-font-size: var(--tile-text-xs);
	--tile-button-sm-gap: 0.25rem;
	--tile-button-sm-height: 1.625rem;
	--tile-button-sm-icon-padding-inline: 0.375rem;
	--tile-button-sm-padding-block: 0 1px;
	--tile-button-sm-padding-inline: 0.5rem;
	--tile-button-sm-radius: 0.375rem;
	--tile-button-xs-font-size: var(--tile-text-xs);
	--tile-button-xs-gap: 0.25rem;
	--tile-button-xs-height: 1.25rem;
	--tile-button-xs-icon-padding-inline: 0.25rem;
	--tile-button-xs-padding-block: 0 1px;
	--tile-button-xs-padding-inline: 0.375rem;
	--tile-button-xs-radius: 0.25rem;
	--tile-calendar-background: var(--tile-surface-base);
	--tile-calendar-border: none;
	--tile-calendar-caption-weight: 600;
	--tile-calendar-cell-padding: 2px;
	--tile-calendar-day-radius: 0.375rem;
	--tile-calendar-day-size: 0.8125rem;
	--tile-calendar-disabled-opacity: 0.4;
	--tile-calendar-focus-shadow: inset 0 0 0 2px var(--tile-brand);
	--tile-calendar-header-height: 2.5rem;
	--tile-calendar-nav-shadow: inset 0 0 0 1px var(--tile-line);
	--tile-calendar-nav-size: 1.5rem;
	--tile-calendar-numerals: tabular-nums;
	--tile-calendar-outside-opacity: 0.4;
	--tile-calendar-padding: 0;
	--tile-calendar-radius: 0.75rem;
	--tile-calendar-today-background: transparent;
	--tile-calendar-today-weight: 600;
	--tile-calendar-weekday-padding: 0.5rem;
	--tile-calendar-weekday-size: smaller;
	--tile-calendar-weekday-weight: 500;
	--tile-calendar-weekdays-margin: 0;
	--tile-calendar-weeks-gap: 0;
	--tile-calendar-weeks-margin: 0;
	--tile-card-background: var(--tile-surface-base);
	--tile-card-border: var(--tile-line);
	--tile-card-content-padding: 0 1rem;
	--tile-card-description-color: var(--tile-text-subtle);
	--tile-card-footer-padding: 0 1rem 1rem;
	--tile-card-gap: 0.5rem;
	--tile-card-header-padding: 1rem 1rem 0;
	--tile-card-hover-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
	--tile-card-radius: 0.5rem;
	--tile-card-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
	--tile-card-title-leading: 1.5;
	--tile-card-title-size: var(--tile-text-base);
	--tile-card-title-weight: 500;
	--tile-chart-axis-color: var(--tile-line);
	--tile-chart-font-size: 13px;
	--tile-chart-grid-color: var(--tile-hairline);
	--tile-chart-grid-dasharray: none;
	--tile-chart-grid-opacity: 1;
	--tile-chart-muted-foreground: var(--tile-text-subtle);
	--tile-chart-tooltip-background: var(--tile-surface-base);
	--tile-chart-tooltip-border: var(--tile-line);
	--tile-chart-tooltip-foreground: var(--tile-text-default);
	--tile-chart-tooltip-radius: 0.5rem;
	--tile-chart-tooltip-shadow: var(--tile-shadow-md);
	--tile-checkbox-background: var(--tile-surface-base);
	--tile-checkbox-border: var(--tile-hairline);
	--tile-checkbox-border-width: 0px;
	--tile-checkbox-checked-background: var(--tile-contrast);
	--tile-checkbox-checked-border: var(--tile-contrast);
	--tile-checkbox-checked-color: var(--tile-contrast-foreground);
	--tile-checkbox-checked-focus-offset: 1px;
	--tile-checkbox-checked-focus-outline: 2px solid var(--tile-brand);
	--tile-checkbox-checked-focus-shadow: 0 0 0 2px var(--tile-brand);
	--tile-checkbox-checked-shadow: 0 0 0 1px var(--tile-contrast);
	--tile-checkbox-error-focus-shadow: 0 0 0 2px var(--destructive);
	--tile-checkbox-error-shadow: 0 0 0 1px var(--destructive);
	--tile-checkbox-focus-border: transparent;
	--tile-checkbox-focus-shadow: 0 0 0 2px var(--tile-brand);
	--tile-checkbox-indicator-size: 0.75rem;
	--tile-checkbox-radius: 0.25rem;
	--tile-checkbox-shadow: 0 0 0 1px var(--tile-hairline);
	--tile-checkbox-size: 1rem;
	--tile-collapsible-focus-shadow: inset 0 0 0 2px var(--tile-brand);
	--tile-collapsible-font-size: var(--tile-text-base);
	--tile-collapsible-font-weight: 500;
	--tile-collapsible-foreground: var(--foreground);
	--tile-collapsible-gap: 0.25rem;
	--tile-collapsible-hover-background: transparent;
	--tile-collapsible-radius: 0.375rem;
	--tile-combobox-list-padding: 0.5rem 0.375rem;
	--tile-combobox-search-padding: 0.5rem 0.875rem;
	--tile-combobox-trigger-min-height: 2.25rem;
	--tile-command-background: var(--tile-surface-base);
	--tile-command-border: var(--tile-hairline);
	--tile-command-dialog-shadow: var(--tile-shadow-lg);
	--tile-command-empty-padding: 2rem;
	--tile-command-font-size: var(--tile-text-base);
	--tile-command-foreground: var(--foreground);
	--tile-command-highlight-background: var(--tile-surface-overlay);
	--tile-command-highlight-foreground: var(--foreground);
	--tile-command-icon-opacity: 1;
	--tile-command-input-gap: 0.75rem;
	--tile-command-input-height: 1.5rem;
	--tile-command-input-padding: 0.75rem 1rem;
	--tile-command-item-padding: 0.375rem 0.5rem;
	--tile-command-item-radius: 0.5rem;
	--tile-command-label-font-weight: 600;
	--tile-command-list-padding: 0.5rem;
	--tile-command-overlay: color-mix(in srgb, var(--tile-overlay) 80%, transparent);
	--tile-command-radius: 0.5rem;
	--tile-command-subtle: var(--tile-text-subtle);
	--tile-destructive-hover: color-mix(in srgb, var(--tile-danger) 90%, black);
	--tile-destructive-muted-foreground: var(--tile-text-danger);
	--tile-dialog-background: var(--tile-surface-base);
	--tile-dialog-border: var(--tile-line);
	--tile-dialog-close-color: var(--tile-text-subtle);
	--tile-dialog-close-focus-shadow: 0 0 0 2px var(--tile-focus);
	--tile-dialog-close-opacity: 1;
	--tile-dialog-close-radius: 0.375rem;
	--tile-dialog-description-color: var(--tile-text-subtle);
	--tile-dialog-description-size: var(--tile-text-base);
	--tile-dialog-header-align: left;
	--tile-dialog-max-width: 24rem;
	--tile-dialog-overlay: color-mix(in srgb, var(--tile-surface-recessed) 80%, transparent);
	--tile-dialog-padding: 2rem;
	--tile-dialog-radius: 0.75rem;
	--tile-dialog-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.03), 0 8px 10px -6px rgb(0 0 0 / 0.03);
	--tile-dialog-title-leading: 2rem;
	--tile-dialog-title-size: 1.5rem;
	--tile-dialog-top: 2rem;
	--tile-dialog-top-desktop: 4rem;
	--tile-dialog-translate-y: 0%;
	--tile-drawer-background: var(--tile-surface-base);
	--tile-drawer-border: var(--tile-line);
	--tile-drawer-close-focus-shadow: 0 0 0 2px var(--tile-focus);
	--tile-drawer-description-color: var(--tile-text-subtle);
	--tile-drawer-footer-padding: 1.5rem;
	--tile-drawer-handle-background: var(--tile-interact);
	--tile-drawer-header-padding: 1.5rem;
	--tile-drawer-overlay: var(--tile-dialog-overlay);
	--tile-drawer-shadow: var(--tile-dialog-shadow);
	--tile-drawer-title-leading: 1.5;
	--tile-drawer-title-size: var(--tile-text-lg);
	--tile-empty-background: var(--tile-control-background);
	--tile-empty-border: var(--tile-fill);
	--tile-empty-border-style: solid;
	--tile-empty-description-color: var(--tile-text-subtle);
	--tile-empty-description-leading: 1.5;
	--tile-empty-description-size: var(--tile-text-base);
	--tile-empty-header-gap: 0.625rem;
	--tile-empty-media-background: transparent;
	--tile-empty-padding: 4rem 2.5rem;
	--tile-empty-radius: 0.75rem;
	--tile-empty-title-size: var(--tile-text-lg);
	--tile-empty-title-tracking: normal;
	--tile-empty-title-weight: 600;
	--tile-field-description-color: var(--tile-text-subtle);
	--tile-field-description-font-size: var(--tile-text-sm);
	--tile-field-description-line-height: 1.375;
	--tile-field-disabled: var(--tile-surface-base);
	--tile-field-gap: 0.5rem;
	--tile-field-hover: var(--tile-tint);
	--tile-field-label-font-size: var(--tile-text-base);
	--tile-field-label-line-height: 1.5;
	--tile-field-message-font-size: var(--tile-text-sm);
	--tile-field-subtle: var(--tile-surface-recessed);
	--tile-font-bold: 700;
	--tile-font-light: 300;
	--tile-font-medium: 500;
	--tile-font-mono: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace);
	--tile-font-normal: 400;
	--tile-font-sans: var(--font-sans, ui-sans-serif, system-ui, sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji');
	--tile-font-semibold: 600;
	--tile-form-description-color: var(--tile-text-subtle);
	--tile-form-description-line-height: 1.375;
	--tile-form-item-gap: 0.5rem;
	--tile-form-label-font-size: var(--tile-text-base);
	--tile-form-label-line-height: 1.5;
	--tile-hover-card-background: var(--tile-surface-base);
	--tile-hover-card-border: var(--tile-line);
	--tile-hover-card-font-size: var(--tile-text-sm);
	--tile-hover-card-leading: calc(1 / 0.85);
	--tile-hover-card-padding: var(--tile-popover-padding);
	--tile-hover-card-radius: var(--tile-popover-radius);
	--tile-hover-card-shadow: var(--tile-shadow-md);
	--tile-info-foreground: #fff;
	--tile-input-background: var(--tile-control-background);
	--tile-input-bare-wrapper-display: contents;
	--tile-input-border: currentColor;
	--tile-input-border-width: 0px;
	--tile-input-compact-gap: 0.25rem;
	--tile-input-compact-line-height: 1.3333333333;
	--tile-input-description-color: var(--tile-text-subtle);
	--tile-input-description-font-size: var(--tile-text-sm);
	--tile-input-description-line-height: 1.375;
	--tile-input-disabled-background: var(--tile-control-background);
	--tile-input-disabled-color: var(--foreground);
	--tile-input-disabled-opacity: 1;
	--tile-input-display: inline-block;
	--tile-input-error-focus-shadow: 0 0 0 1.5px color-mix(in oklch, var(--destructive) 50%, transparent);
	--tile-input-error-shadow: 0 0 0 1px var(--destructive);
	--tile-input-focus-border: currentColor;
	--tile-input-focus-outline: auto 1px -webkit-focus-ring-color;
	--tile-input-focus-outline-style: none;
	--tile-input-focus-shadow: 0 0 0 1.5px color-mix(in oklch, var(--tile-focus) 50%, transparent);
	--tile-input-font-size: var(--tile-text-base);
	--tile-input-gap: 0.375rem;
	--tile-input-group-addon-background: transparent;
	--tile-input-group-background: var(--tile-input-background);
	--tile-input-group-border: var(--tile-input-border);
	--tile-input-group-border-width: var(--tile-input-border-width);
	--tile-input-group-error-focus-shadow: var(--tile-input-error-focus-shadow);
	--tile-input-group-error-shadow: var(--tile-input-error-shadow);
	--tile-input-group-focus-border: var(--tile-input-focus-border);
	--tile-input-group-focus-shadow: var(--tile-input-focus-shadow);
	--tile-input-group-font-size: var(--tile-input-font-size);
	--tile-input-group-height: var(--tile-input-height);
	--tile-input-group-line-height: var(--tile-input-line-height);
